{"yol":"telefon.js","icerik":"export function telefonNormalle(numara) {
  // Tüm özel karakterleri kaldır
  const rakamlar = numara.replace(/\D/g, '')

  // 0 ile başlayan numara ise 0'ı kaldır
  if (rakamlar.startsWith('0')) {
    rakamlar = rakamlar.slice(1)
  }

  // +90 ile başlayan numara ise sadece + ekle
  if (rakamlar.startsWith('90')) {
    return `+${rakamlar}`
  }

  // Diğer durumlarda +90 ekle
  return `+90${rakamlar}`
}"}
